import{_ as t,o,c as s,a2 as a}from"./chunks/framework.Boholvbs.js";const u=JSON.parse('{"title":"The Android app","description":"","frontmatter":{},"headers":[],"relativePath":"android.md","filePath":"android.md"}'),n={name:"android.md"};function d(r,e,i,h,c,l){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="the-android-app" tabindex="-1">The Android app <a class="header-anchor" href="#the-android-app" aria-label="Permalink to &quot;The Android app&quot;">​</a></h1><p><code>android/</code> is nanoMuse for the phone: <a href="https://github.com/OpenMinis/OpenMinis" target="_blank" rel="noreferrer">OpenMinis</a> 1.13 (GPL-3.0) — a native app whose agent runs <strong>on the phone</strong>, with a Linux shell, a browser, MCP servers, skills and scheduled tasks inside the APK — with nanoMuse&#39;s own identity, design and features on top. Everything of nanoMuse&#39;s lives in <code>io.github.nanomuse.*</code>; edits inside OpenMinis files are marked <code>// nanoMuse:</code>. The history of this choice is in <a href="./roadmap">roadmap.md</a>; what came before it (a WebView around a Python server, two APK flavours) is kept as a design record in <a href="https://github.com/nano-muse/nanoMuse/blob/main/docs/archive/android-python-line.md" target="_blank" rel="noreferrer">archive/android-python-line.md</a> and is not what you download today.</p><p>One APK, one architecture: <code>nanoMuse-&lt;version&gt;-arm64.apk</code> (arm64-v8a, Android 8.0 / API 26 or newer, <code>targetSdk</code> 35). Every release is signed with the same key, so a newer APK installs over the old one and keeps its data. No Play Store listing: <em>Settings → Version</em> shows the installed build next to the newest release (<code>nanomuse.cn/dl/index.json</code> first, this repository&#39;s GitHub Releases second — <em>Latest 0.1.x — you have it</em> / <em>0.1.x is out — tap to update</em>) and offers the download.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><ol><li>Download <code>nanoMuse-&lt;version&gt;-arm64.apk</code> from the <a href="https://github.com/nano-muse/nanoMuse/releases/latest" target="_blank" rel="noreferrer">latest release</a>. Verify with <code>sha256sum -c nanoMuse-&lt;version&gt;-arm64.apk.sha256</code> if you like.</li><li>Open it. Android asks once to allow installs from your browser or file manager.</li><li><strong>Sign in.</strong> The first screen is the account: a phone number or an e-mail address, a code — or a password once you have set one. It is what lets your devices work as one (<a href="./hub">hub.md</a>) and brings a model to start with (<a href="./cloud">cloud.md</a>: a free pool per account — ¥10 at the time of writing — and more for each friend invited, and for them; the app prints the relay&#39;s current figures; then <a href="./own-key">your own key</a>). Then choose which model answers: the account&#39;s own, or a key of your own (any OpenAI-compatible endpoint, or the OAuth sign-ins the app ships with). Two models are set, not one: the <strong>chat model</strong> (the account&#39;s menu opens on <code>deepseek-v4.1-flash</code>; picking another in the Cloud group makes new chats follow it) and the <strong>Hands model</strong> under <em>Settings → Hands</em>, the one that looks at the screen (<code>qwen3.8-27b</code> — the account&#39;s, or the same model under your own key; you can pin any model that sees). Running everything yourself with no account at all is the runtime&#39;s <code>cloud.required = false</code>; the phone app asks for the account.</li><li>Optional: the two permissions that let the agent use your phone&#39;s apps (skippable and revocable), and <em>Settings → Image &amp; video models</em> for a look that can change and move.</li></ol><p><strong>Your own relay.</strong> The sign-in screen talks to nanoMuse Cloud unless you tell it otherwise: <em>Use a different server</em> under the sign-in form takes the address of a relay you run yourself (<a href="./cloud">cloud.md</a>, <code>cloud/docker-compose.yml</code>), <em>Check</em> asks its <code>/healthz</code> and shows the version it answers with, <em>Use this server</em> keeps the address across launches. <code>https://</code> is required for anything outside your own network; plain <code>http://</code> is accepted for a private address (<code>10.x</code>, <code>172.16–31.x</code>, <code>192.168.x</code>, <code>localhost</code>, a <code>.local</code> or <code>.ts.net</code> name). Settings → Account shows <em>Server: <code>&lt;host&gt;</code></em> with <em>Change</em>, which signs the phone out first — the key it holds belongs to the server that issued it. Everything the app does with the account (sign-in, the hub, sync, usage, the model menu) goes to that address.</p><h2 id="what-the-phone-does" tabindex="-1">What the phone does <a class="header-anchor" href="#what-the-phone-does" aria-label="Permalink to &quot;What the phone does&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>The agent, on the phone</strong></td><td>A sandboxed Alpine Linux, a real shell, files, a browser, MCP servers, skills in the Agent Skills format, memory, scheduled tasks; approvals before deleting, sending or paying. The model is the account&#39;s or your own; nothing you say passes through the project&#39;s relay when you use your own key.</td></tr><tr><td><strong>Hands</strong> (<code>hands/</code>)</td><td>With <em>Hands</em> on and the accessibility service enabled, the agent looks at the phone&#39;s screen and taps, types and swipes in its apps — the last rung after APIs, fetches and the browser. A stage over the app shows where it is about to tap and a capsule with the step and <strong>Stop</strong>; when a tap would send, post or delete, the capsule itself asks — <strong>Allow</strong> / <strong>Deny</strong>, the same request the chat card and the notification show — so you are not pulled back into nanoMuse (money is confirmed with the screen lock in the chat card; the capsule offers <em>Open</em> for that one). Passwords and codes are always yours to type. <a href="./gui">gui.md</a> is the design record; the app&#39;s own hands are in <code>io.github.nanomuse.hands</code>.</td></tr><tr><td><strong>Reach</strong> (<code>reach/</code>)</td><td>Your computers, from the phone: &quot;say it on the phone, it gets done there&quot; — a shell command, a file, the computer&#39;s screen, or a whole task for the nanoMuse running there. The way in is the hub (next row): install nanoMuse Desktop on the computer and sign in with the same account, and it is under <em>Account → Devices</em> within seconds, on any network — the only way since 0.1.24 (the local-network host script is gone). <em>Settings → Computers</em> lists the account&#39;s computers and says which account the phone uses, since a missing computer has nearly always signed in with another one. Approvals are decided on the phone before anything is sent. <a href="./every-device">every-device.md</a>.</td></tr><tr><td><strong>The hub</strong> (<code>hub/</code>)</td><td>Every signed-in device of the account meets on the relay&#39;s hub: the phone sees your computers, asks them to do things, gets their approvals as cards, and can be asked by them. A foreground service keeps it reachable in the background (Android 13+ asks for the notification permission for that). <a href="./hub">hub.md</a>.</td></tr><tr><td><strong>Coding agents</strong> (<code>ui/coding/</code>)</td><td>The Cursor, Codex and Claude Code sessions on your computers, seen and steered from the phone. <a href="./coding-agents">coding-agents.md</a>.</td></tr><tr><td><strong>Account</strong> (<code>ui/cloud/</code>)</td><td>Who is signed in, the password, every device holding a key, usage by kind and by model, the ways out. When the free pool is spent or past 80 %, the account page and the refused turn show the two ways on: an invitation, and your own key — Alibaba Cloud Bailian first for people in mainland China (the UI in simplified Chinese, a phone-number sign-in, or the relay saying so), OpenRouter first everywhere else with <em>Sign in with OpenRouter</em> as the one button (Bailian only signs up accounts from the mainland); the other vendor is a text link away.</td></tr><tr><td><strong>The browser handed over</strong> (<code>browser/</code>)</td><td>A page that needs you — a login, a verification code, a payment, a CAPTCHA — is handed over instead of described: <code>browser_use</code>&#39;s <code>hand_over</code> action opens the agent&#39;s own tab (same WebView, same session) in the browser sheet with the agent&#39;s hold released, a <strong>Your turn</strong> card above the composer says what the page asks of you with <em>Open the page</em> and <em>Done, continue</em>, the sheet carries the same line and button, and the tool call waits for <em>Done</em> (fifteen minutes at most) before the agent goes on from the page as it is. <code>io.github.nanomuse.browser.BrowserHandOver</code>.</td></tr><tr><td><strong>Connectors</strong> (<code>connectors/</code>, <code>ui/connectors/</code>)</td><td>The services the agent can be let into — the desktop&#39;s catalogue of 75 remote MCP servers (Notion, Linear, GitHub, GitLab, Slack, Stripe, Miro, …), shipped as <code>assets/nanomuse/connectors.json</code>. The only Settings row for all of this is <em>Connectors</em>; the upstream MCP editor (by address, by command, imported JSON) is <em>Your own servers</em> at the end of the page. Open servers add with a tap; a key service takes the key; an OAuth service runs the MCP authorization flow (discovery, dynamic client registration, PKCE in a Custom Tab) and the token goes into the entry&#39;s <code>Authorization</code> header for the in-guest MCP client, refreshed at app start; a service whose authorization server registers no clients (<code>clientIdRequired</code> — GitHub, Slack, Discord, HubSpot, Render, Bitrise, PagerDuty, Box) asks for an OAuth client id and secret made at the vendor&#39;s developer page with the app&#39;s callback address, which the sheet shows and copies. A connected service is an MCP server entry under the same id — <em>Your own servers</em> manages it too. What is connected is shared with the account&#39;s other devices through the relay profile — the entries (id, label, address, kind of auth, which device, when), never a token — so the page also lists <em>On your other devices</em>: a service connected on the desktop shows as <em>Connected on &lt;device&gt; — sign in here to use it on this phone</em>, one tap into the same sheet.</td></tr><tr><td><strong>The chat, plain</strong></td><td>While the agent works, the line under its avatar names the step under way — <em>nanoMuse is using Shell</em>, <em>Writing the reply</em>, <em>On it: book the table</em> — never a state of mind. The tool pills, the Computer sheet and the floating step bar are <strong>off by default</strong>; <em>Settings → Appearance → Show the agent&#39;s steps</em> turns them on. With them on, a finished step reads <em>nanoMuse used Shell · Done</em>, and its sheet closes on ×, swipe or Back.</td></tr></tbody></table><p>The web console of the same account is at the relay (<code>/app</code>), the desktop app in <a href="./desktop">desktop.md</a>; the phone, the desktop and the web share the design language described in <a href="./brand">brand.md</a>.</p><h2 id="privacy-and-permissions" tabindex="-1">Privacy and permissions <a class="header-anchor" href="#privacy-and-permissions" aria-label="Permalink to &quot;Privacy and permissions&quot;">​</a></h2><p>The relay keeps an account id, a masked identifier, usage counts and the agent&#39;s name and look (so your devices match) — never message content (<a href="./privacy">privacy.md</a>). On the phone, API keys, the account key and Reach pairing tokens are in <code>EncryptedSharedPreferences</code>; the backup rules (<code>res/xml/nanomuse_backup_rules.xml</code>, <code>nanomuse_data_extraction_rules.xml</code>) keep every secret store out of device backups and transfers. Hands needs the accessibility service and the overlay permission, both optional and both revocable from the same screen; a step that sends something — a tap on <em>Send</em>, or Enter in a message field of a messenger — is approved one at a time, and <em>for this chat</em> answers stay bound to the app or address they were given for. Another device of your account that wants to run, read or write something on the phone (hub <code>shell</code>, <code>files</code>, <code>open</code>, <code>screen</code>…) is approved by the person holding the phone first — <em>once</em> or <em>always for that device</em>, revocable under Permissions. The app allows plain <code>http://</code> only for addresses on your own network (<code>10.x</code>, <code>172.16–31.x</code>, <code>192.168.x</code>, <code>.local</code> names) — a model server or a computer of your own — and refuses it at the provider URL field for anything else (<code>io.github.nanomuse.net.LanOnly</code>); the relay and the hub are TLS only. The in-app web view is not exported to other apps.</p><h2 id="building-it-yourself" tabindex="-1">Building it yourself <a class="header-anchor" href="#building-it-yourself" aria-label="Permalink to &quot;Building it yourself&quot;">​</a></h2><p>JDK 17 and the Android SDK (Android Studio installs both); <code>scripts/android/env.sh</code> sets the environment on a bare machine. The project is under <code>android/src/android</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> android/src/android</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :app:assembleDebug</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # app/build/outputs/apk/debug/app-debug.apk</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :app:assembleRelease</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # signed with android/keystore.properties when present</span></span></code></pre></div><p><code>scripts/rebrand.py</code> carries the version (<code>VERSION_NAME</code>, <code>VERSION_CODE</code>) and applies nanoMuse&#39;s naming to the OpenMinis tree; <code>android/BUILDING.md</code> covers the native pieces. Without a signing key the release build is signed with the debug key, which installs but cannot update a properly signed build. To sign, create a key once and keep it outside the repository:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">keytool</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -genkeypair</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -keystore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nanomuse-release/nanomuse.jks</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -alias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nanomuse</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        -keyalg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RSA</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -keysize</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4096</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -validity</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10950</span></span></code></pre></div><p>and put its four values in <code>android/keystore.properties</code> (git-ignored: <code>storeFile</code>, <code>storePassword</code>, <code>keyAlias</code>, <code>keyPassword</code>).</p><h2 id="releases" tabindex="-1">Releases <a class="header-anchor" href="#releases" aria-label="Permalink to &quot;Releases&quot;">​</a></h2><p><code>.github/workflows/android.yml</code> builds the debug APK on every change under <code>android/</code> (the &quot;debug APK · arm64-v8a&quot; check). A release is made from a tag by <code>scripts/release-apk.sh &lt;version&gt;</code>: it checks the version against <code>rebrand.py</code> and Gradle, builds <code>:app:assembleRelease</code> with the release key, writes <code>dist/nanoMuse-&lt;version&gt;-arm64.apk</code> and its <code>.sha256</code>, and with <code>--publish</code> tags <code>v&lt;version&gt;</code> and attaches both to the GitHub release with the notes from <code>docs/releases/v&lt;version&gt;.md</code>. A debug-signed APK never goes on a release, because it could not be updated by a properly signed one. The <code>versionName</code> must match the tag, like the Python package&#39;s version does.</p><h2 id="where-things-are" tabindex="-1">Where things are <a class="header-anchor" href="#where-things-are" aria-label="Permalink to &quot;Where things are&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path (<code>android/src/android/app/src/main/java/io/github/nanomuse/</code>)</th><th>Does</th></tr></thead><tbody><tr><td><code>cloud/NanoMuseCloud.kt</code></td><td>The account: sign-in with a code or a password, the key in the encrypted store, <code>/v1/me</code>, usage, sessions, the localized error sentences; the relay&#39;s menu and its two defaults (<code>for: chat</code> / <code>for: gui</code>)</td></tr><tr><td><code>cloud/Region.kt</code>, <code>cloud/OwnKeyPresets.kt</code>, <code>cloud/ProfileSync.kt</code></td><td>Which own-key vendor comes first (mainland → Bailian, else OpenRouter); the pre-filled provider forms; the relay profile (name, look, connectors) pulled and pushed</td></tr><tr><td><code>hub/</code></td><td><code>Hub</code> (state, device identity, settings), <code>HubClient</code> (the socket with backoff; stops when the relay refuses the key), <code>HubService</code> (the foreground service), <code>HubActions</code> (what other devices may ask this phone), <code>HubErrors</code> (failures in words)</td></tr><tr><td><code>reach/</code></td><td><code>Computers</code> (paired computers, tokens in the encrypted store), the offload handler that sends work to a computer</td></tr><tr><td><code>hands/</code></td><td>The accessibility service as the hand, the stage and the capsule, the screen reader; <code>Hands.screenModel</code> picks the Hands model (chosen → the Cloud&#39;s <code>qwen3.8-27b</code> → the same under your own key → a chat model that sees → the Vision Group)</td></tr><tr><td><code>ui/coding/</code></td><td>The coding agents of your computers</td></tr><tr><td><code>connectors/</code>, <code>ui/connectors/</code></td><td>The connectors catalogue (<code>ConnectorsCatalogue</code> reads the asset), MCP authorization discovery + registration (<code>McpAuthDiscovery</code>), connecting and token refresh (<code>Connectors</code>), what this phone connected as published to the profile and what the other devices did (<code>SharedConnectors</code>), the Settings → Connectors page</td></tr><tr><td><code>ui/cloud/</code></td><td>Sign-in, the Account screen, the Devices section</td></tr><tr><td><code>res/values*/nm_strings.xml</code></td><td>Every nanoMuse string, in English, 简体中文 and 繁體中文 (the three files carry the same keys)</td></tr></tbody></table>`,21)])])}const m=t(n,[["render",d]]);export{u as __pageData,m as default};
